func scopeUnitChecked(selectedCSV, unitID string, recommended bool) bool {
	if selectedCSV == "" {
		return recommended
	}
	selectedCSV = strings.TrimPrefix(selectedCSV, "submitted:")
	for _, selected := range strings.Split(selectedCSV, ",") {
		if selected == unitID {
			return true
		}
	}
	return false
}
func catalogBrowseURL(connectionID, bookID string) string {
	if bookID == "" {
		return "/catalog?connection=" + url.QueryEscape(connectionID)
	}
	return "/catalog?connection=" + url.QueryEscape(connectionID) + "&book_id=" + url.QueryEscape(bookID)
}
func titleSourceLabel(source string) string {
	if source == domain.UnitTitleHeading {
		return "title from document heading"
	}
	return "fallback title from manifest ID"
}
func categoryLabel(category domain.EPUBUnitCategory) string {
	return strings.ReplaceAll(string(category), "_", " ")
}
func recommendationLabel(classification domain.EPUBUnitClassification) string {
	if classification.RecommendedInclusion && classification.Confidence < domain.EPUBConfidenceHighMinimum {
		return "Include — review suggested"
	}
	if classification.RecommendedInclusion {
		return "Include"
	}
	if classification.Category == domain.EPUBCategoryUnknown {
		return "Exclude — review required"
	}
	return "Exclude"
}
func recommendationExplanation(classification domain.EPUBUnitClassification) string {
	if classification.RecommendedInclusion && classification.Confidence < domain.EPUBConfidenceHighMinimum {
		return "Included as plausible main matter; review is suggested because the structural evidence is not high confidence."
	}
	if classification.RecommendedInclusion {
		return "Included because high-confidence structural evidence identifies main matter."
	}
	if classification.Category == domain.EPUBCategoryUnknown && hasReferenceLikeEvidence(classification.Reasons) {
		return "Excluded because reference-like evidence does not make an unknown unit safe for automatic inclusion; review it before adding it."
	}
	if classification.Category == domain.EPUBCategoryUnknown {
		return "Excluded because unknown structural evidence is not safe for automatic inclusion; review it before adding it."
	}
	return "Excluded because the structural category is outside the recommended main-matter scope."
}
func hasReferenceLikeEvidence(reasons []domain.EPUBClassificationReason) bool {
	for _, reason := range reasons {
		value := strings.ToLower(reason.Signal + " " + reason.Message)
		if strings.Contains(value, "reference") || strings.Contains(value, "citation") || strings.Contains(value, "bibliograph") || strings.Contains(value, "index") || strings.Contains(value, "register") || strings.Contains(value, "quellen") || strings.Contains(value, "literatur") {
			return true
		}
	}
	return false
}
func scopeReviewURL(book domain.SourceMaterialSummary) string {
	if book.ReviewedScopeID == "" {
		return "/books/" + book.Source.ID + "/scope"
	}
	return "/books/" + book.Source.ID + "/scope?preset=prior&prior_scope_id=" + url.QueryEscape(book.ReviewedScopeID)
}
func scopePresetURL(review epubScopeView, preset string) string {
	value := "/books/" + review.Book.ID + "/scope?preset=" + url.QueryEscape(preset)
	if review.PriorScope != nil {
		value += "&prior_scope_id=" + url.QueryEscape(review.PriorScope.ScopeID)
	}
	return value
}
func completedAnalysisURL(book domain.SourceMaterialSummary, history []domain.AnalysisJob) string {
	for _, job := range history {
		if historyURL := analysisHistoryURL(book.Source.ID, job); strings.Contains(historyURL, "/analyses/") {
			return historyURL
		}
	}
	return ""
}
func completedAtLabel(value *time.Time) string {
	if value == nil || value.IsZero() {
		return "Unavailable"
	}
	return value.UTC().Format("2006-01-02 15:04:05 UTC")
}

func knownCoveragePercent(coverage domain.AnalysisCoverage) float64 {
	if coverage.AnalyzableTokenCount == 0 {
		return 0
	}
	return min(float64(coverage.KnownTokenCount)*100/float64(coverage.AnalyzableTokenCount), 100)
}

func activeCampaignCoveragePercent(coverage domain.AnalysisCoverage) float64 {
	if coverage.AnalyzableTokenCount == 0 {
		return 0
	}
	return min(float64(coverage.KnownTokenCount+coverage.ActiveCampaignTokenCount)*100/float64(coverage.AnalyzableTokenCount), 100)
}

func concentrationPercent(projection domain.CoverageProjection) float64 {
	if projection.EligibleTokenCount == 0 {
		return 0
	}
	return float64(projection.OccurrenceCount) * 100 / float64(projection.EligibleTokenCount)
}

func projectedCoveragePercent(projection domain.CoverageProjection, analyzableTokens int64) float64 {
	if analyzableTokens == 0 {
		return 0
	}
	return min(float64(projection.ProjectedTokenCount)*100/float64(analyzableTokens), 100)
}

func longSentencePercent(profile domain.TextProfile) float64 {
	if profile.SentenceCount == 0 {
		return 0
	}
	return float64(profile.LongSentenceCount) * 100 / float64(profile.SentenceCount)
}

func hasAnalysisWarnings(coverage domain.AnalysisCoverage) bool {
	if coverage.TextProfile == nil {
		return false
	}
	return coverage.TextProfile.SentenceCount == 0 ||
		coverage.TextProfile.EmptySentenceCount > 0 ||
		(coverage.TextProfile.NormalizedTokenCount > 0 && coverage.AnalyzableTokenCount == 0)
}

func corpusUnitLabel(unit domain.CorpusSelectedUnit) string {
	if strings.TrimSpace(unit.Title) != "" {
		return unit.Title
	}
	if strings.TrimSpace(unit.SourceHref) != "" {
		return unit.SourceHref
	}
	return unit.UnitID
}

